"""Sequential batch-job runner implementing Meridian CRM error semantics."""


def run_jobs(jobs: list[dict], executor) -> list[dict]:
    """Execute scheduled jobs sequentially and return an attempt log."""
    run_log: list[dict] = []

    for job in jobs:
        error_config = job["on_error"]
        policy = error_config["policy"]
        attempts = 0

        if policy == "RETRY":
            maximum_attempts = error_config["retries"] + 1

            for _ in range(maximum_attempts):
                attempts += 1
                try:
                    executor(job)
                except Exception:
                    continue

                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                break

            continue

        attempts = 1
        try:
            executor(job)
        except Exception:
            if policy == "CONTINUE":
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "skip",
                        "audits": ["BATCH_ROWSKIP"],
                    }
                )
                continue

            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "abort",
                    "audits": [],
                }
            )
            break

        run_log.append(
            {
                "name": job["name"],
                "attempts": attempts,
                "outcome": "ok",
                "audits": [],
            }
        )

    return run_log
